import{_ as o,a,c as n,ac as t}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"第一册：英语初阶 · 单元 2 复习与自测 · 第46–48课","description":"L25–L48 原创练习和答案解析。","frontmatter":{"title":"第一册：英语初阶 · 单元 2 复习与自测 · 第46–48课","description":"L25–L48 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-1/unit-02/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 单元 2 复习与自测","summary":"L25–L48 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 2 复习与自测 · 第39–45课","link":"/life/english/new-concept/book-1/unit-02/review-part-03"},"next":{"text":"第一册：英语初阶 · 单元 3：日常规律、时间与过去状态","link":"/life/english/new-concept/book-1/unit-03/overview"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 2 复习与自测 · 第39–45课","link":"/life/english/new-concept/book-1/unit-02/review-part-03"},"next":{"text":"第一册：英语初阶 · 单元 3：日常规律、时间与过去状态","link":"/life/english/new-concept/book-1/unit-03/overview"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-02/review-part-04.md","filePath":"life/english/new-concept/book-1/unit-02/review-part-04.md"}'),s={name:"life/english/new-concept/book-1/unit-02/review-part-04.md"};function i(r,e,l,c,p,d){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="第一册-英语初阶-·-单元-2-复习与自测-·-第46–48课" tabindex="-1">第一册：英语初阶 · 单元 2 复习与自测 · 第46–48课 <a class="header-anchor" href="#第一册-英语初阶-·-单元-2-复习与自测-·-第46–48课" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 2 复习与自测 · 第46–48课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-02/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/unit-02/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-02/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-02/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-02/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-46-·-can-表能力" tabindex="-1">Lesson 46 · can 表能力 <a class="header-anchor" href="#lesson-46-·-can-表能力" aria-label="Permalink to &quot;Lesson 46 · can 表能力 {#lesson-46-·-can-表能力}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Can you print the report today?</p><h3 id="练习-1-21" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-21" aria-label="Permalink to &quot;练习 1 {#练习-1-21}&quot;">​</a></h3><p>将 You can print it. 改为一般疑问句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Can you print it?</p><p><strong>解析：</strong> 按本课规则判断：can 后接动词原形，对所有人称保持 can，不增加 s。否定为 cannot 或 can&#39;t；问句把 can 放在主语前，不另加 do。can 表能力时说明能否完成动作，不等于动作正在发生。副词可说明做得怎样，如 type quickly；形容词常用于描述人或物。</p></details><p><strong>表达迁移：</strong> 围绕“说明能够完成的工作”写两至三句，再读给同伴听。至少使用一次can 表能力，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Can you print the report today? My colleague can translate this message.</p><p>Can 前置形成问句，you 为主语，print 为原形；today 说明希望完成任务的时间。 My colleague 是第三人称单数，但 can 不加 s；translate 用原形，this message 为宾语。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-046">回看本课</a></p><h2 id="lesson-47-·-实义动词的一般现在时问句" tabindex="-1">Lesson 47 · 实义动词的一般现在时问句 <a class="header-anchor" href="#lesson-47-·-实义动词的一般现在时问句" aria-label="Permalink to &quot;Lesson 47 · 实义动词的一般现在时问句 {#lesson-47-·-实义动词的一般现在时问句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Do you like coffee without sugar?</p><h3 id="练习-1-22" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-22" aria-label="Permalink to &quot;练习 1 {#练习-1-22}&quot;">​</a></h3><p>填助动词：___ you like coffee?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Do</p><p><strong>解析：</strong> 按本课规则判断：主语为 I/you/we/they 时，实义动词的一般现在时问句通常借助 do；否定用 don&#39;t + 原形。like 表较稳定的喜好，want 表当前想要。Do you like tea? 与 Do you want some tea? 关注点不同。不要在实义动词前错误加 be；回答时用 Yes, I do，不重复整个宾语。</p></details><p><strong>表达迁移：</strong> 围绕“询问饮食喜好和即时需求”写两至三句，再读给同伴听。至少使用一次实义动词的一般现在时问句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Do you like coffee without sugar? I do not want a cold drink now.</p><p>Do 帮助 like 形成一般疑问句；coffee 是宾语，without sugar 修饰所说的咖啡，表示不加糖。 I do not want 是一般现在时否定；want 保持原形，a cold drink 为宾语，now 说明当前需求。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-047">回看本课</a></p><h2 id="lesson-48-·-实义动词的一般现在时问句" tabindex="-1">Lesson 48 · 实义动词的一般现在时问句 <a class="header-anchor" href="#lesson-48-·-实义动词的一般现在时问句" aria-label="Permalink to &quot;Lesson 48 · 实义动词的一般现在时问句 {#lesson-48-·-实义动词的一般现在时问句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I do not want a cold drink now.</p><h3 id="练习-1-23" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-23" aria-label="Permalink to &quot;练习 1 {#练习-1-23}&quot;">​</a></h3><p>补否定：I ___ not want a cold drink.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> do</p><p><strong>解析：</strong> 按本课规则判断：主语为 I/you/we/they 时，实义动词的一般现在时问句通常借助 do；否定用 don&#39;t + 原形。like 表较稳定的喜好，want 表当前想要。Do you like tea? 与 Do you want some tea? 关注点不同。不要在实义动词前错误加 be；回答时用 Yes, I do，不重复整个宾语。</p></details><p><strong>表达迁移：</strong> 围绕“询问饮食喜好和即时需求”写两至三句，再读给同伴听。至少使用一次实义动词的一般现在时问句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I do not want a cold drink now. Do you like coffee without sugar?</p><p>I do not want 是一般现在时否定；want 保持原形，a cold drink 为宾语，now 说明当前需求。 Do 帮助 like 形成一般疑问句；coffee 是宾语，without sugar 修饰所说的咖啡，表示不加糖。</p></details><p><a href="/life/english/new-concept/book-1/unit-02/lesson-048">回看本课</a></p>',28)])])}const g=o(s,[["render",i]]);export{h as __pageData,g as default};
